"""Generate the canonical cross-stage evaluation manifest from repository artifacts."""
from __future__ import annotations
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]
OUT_JSON = ROOT / "docs/NESTLINE-EVALUATION-MANIFEST.json"
OUT_MD = ROOT / "docs/NESTLINE-EVALUATION-MANIFEST.md"
BASE = "796c05cd29a055188e86685990078709fca0bfbc"
SPECS = [
 ("phase-1-contract",0,"evals/phase_1_contract.jsonl","synthetic","deterministic contract evaluator","all cases","docs/STAGE-0-CHECK-RESULTS.json","Visible development contracts; not clinical validation."),
 ("journey-resolver",3,"evals/journey_resolver_set.jsonl","synthetic","deterministic journey evaluator","all cases","docs/STAGE-3-CHECK-RESULTS.json","Uses a fixed test clock."),
 ("stage4-document-provider",4,"evals/stage4_document_provider_benchmark.jsonl","fictional exact-hash documents","prepared provider comparison","all schema/provenance fields; provider run pending",None,"No production document provider selected; no live extraction run."),
 ("stage5-retrieval",5,"evals/stage5_retrieval_development.jsonl","synthetic controlled fixtures","hybrid retrieval evaluator","all cases and zero forbidden retrievals","docs/STAGE-5-RETRIEVAL-METRICS.json","No production published corpus exists."),
 ("stage5-paraphrases",5,"evals/stage5_retrieval_paraphrases_v1.jsonl","synthetic controlled fixtures","retrieval paraphrase evaluator","all cases","docs/STAGE-5-PARAPHRASE-EVAL-RESULTS.json","Development set, not sealed holdout."),
 ("stage6-safety",6,"evals/stage6_safety_development.jsonl","synthetic safety language","deterministic route evaluator","100% curated critical routes; zero ordinary generation on stopped routes","docs/STAGE-6-SAFETY-EVAL-RESULTS.json","Draft specification; not clinical validation."),
 ("stage7-orchestration",7,"evals/stage7_orchestration_development.jsonl","fictional/synthetic","deterministic orchestration evaluator","all cases","docs/STAGE-7-EVAL-RESULTS.json","Fixture provider only."),
 ("stage7-live-provider",7,"evals/stage7_live_provider_development.jsonl","fictional frozen evidence packets","live configured-provider plus Stage 8 validator","all automated cases plus separate human tone review","docs/STAGE-7-XAI-LIVE-PROVIDER-BENCHMARK.json","Candidate benchmark; no provider selected."),
 ("stage8-validation",8,"evals/stage8_validation_development.jsonl","fictional/synthetic","seven-control validation evaluator","all critical cases","docs/STAGE-8-EVAL-RESULTS.json","Deterministic development evaluation."),
 ("stage8-sealed-holdout-manifest",8,"evals/stage8_controlled_holdout_manifest.json","sealed IDs only","independent future evaluation","not run in this pass",None,"Answers remain unopened and are not used for tuning."),
 ("stage9-product-experience",9,"evals/stage9_product_experience.jsonl","fictional UI fixtures","existing Stage 9 evaluator","historical accepted result","docs/STAGE-9-EVAL-RESULTS.json","Listed for denominator reconciliation only; Stage 9 was not modified."),
 ("stage10-state-lifecycle",10,"evals/stage10_state_lifecycle.jsonl","fictional/synthetic","state lifecycle evaluator","all cases and zero unauthorized writes","docs/STAGE-10-EVAL-RESULTS.json","Does not authorize deployment or real clinician operations."),
]
def load_cases(rel):
 p=ROOT/rel
 if p.suffix==".jsonl":
  rows=[json.loads(x) for x in p.read_text(encoding="utf-8").splitlines() if x.strip()]
  return rows
 data=json.loads(p.read_text(encoding="utf-8"))
 if isinstance(data,list): return data
 for key in ("cases","case_ids","items"):
  if key in data:
   value=data[key]
   return value if isinstance(value,list) else []
 return []
def case_id(row,index):
 if isinstance(row,str): return row
 return str(row.get("case_id") or row.get("id") or row.get("test_id") or f"item-{index+1}")
def main():
 datasets=[]
 for name,stage,path,input_class,evaluator,threshold,result,limits in SPECS:
  cases=load_cases(path)
  datasets.append({"dataset_id":name,"stage":stage,"path":path,"case_count":len(cases),"case_ids":[case_id(row,i) for i,row in enumerate(cases)],"input_data_class":input_class,"expected_output_or_route":"Defined per visible case; sealed answers are excluded.","evaluator_type":evaluator,"pass_threshold":threshold,"latest_result_artifact":result,"result_commit":"working tree based on "+BASE,"known_limitations":[limits]})
 payload={"schema_version":"nestline-evaluation-manifest-v1","base_commit":BASE,"sealed_holdout_accessed":False,"datasets":datasets,"totals":{"datasets":len(datasets),"cases_or_ids":sum(x["case_count"] for x in datasets)}}
 OUT_JSON.write_text(json.dumps(payload,indent=2,sort_keys=True)+"\n",encoding="utf-8")
 lines=["# Canonical evaluation manifest","","Generated by `python -m scripts.build_evaluation_manifest`. Older reports remain historical evidence; this table owns current dataset denominators.","",f"Base: `{BASE}`. Sealed holdout answers accessed: **no**.","","| Dataset | Stage | Cases/IDs | Input class | Evaluator | Threshold | Result | Limitation |","|---|---:|---:|---|---|---|---|---|"]
 for x in datasets:
  result=x["latest_result_artifact"] or "not run / none"
  lines.append(f"| {x['dataset_id']} | {x['stage']} | {x['case_count']} | {x['input_data_class']} | {x['evaluator_type']} | {x['pass_threshold']} | {result} | {x['known_limitations'][0]} |")
 lines += ["",f"Total registered datasets: **{len(datasets)}**; visible cases or sealed IDs: **{payload['totals']['cases_or_ids']}**."]
 OUT_MD.write_text("\n".join(lines)+"\n",encoding="utf-8")
 print(json.dumps(payload["totals"],sort_keys=True))
 return 0
if __name__=="__main__": raise SystemExit(main())